#pragma once

#include <Arduino.h>
#include "buddhabox/dynamics/low_pass_gate.h"
#include "buddhabox/io/analog_input.h"
#include "buddhabox/io/switch_input.h"
#include "buddhabox/mod/envelope.h"
#include "buddhabox/osc/oscillator.h"
#include "buddhabox/util/range.h"

// The engine lights PC13 when audio runs late. An LED patched
// to PC13 needs that turned off: add -D BB_OVERRUN_LED=0 to
// build_flags.
#include "buddhabox/engine/audio_engine.h"
#if BB_OVERRUN_LED
#warning "LED on PC13 clashes with the overrun LED: add -D BB_OVERRUN_LED=0"
#endif

// A namespace keeps module names such as `slope` from clashing
// with framework functions of the same name.
namespace patch {
using namespace bb;

int ctl_count_ = 0; // samples since last control update
volatile float pitch_v_ = 0.0f; // shared with the audio interrupt
AnalogInput pitch(PA1);
Range pitchRange;
volatile float button_v_ = 0.0f; // shared with the audio interrupt
SwitchInput button(PB3);
volatile float light_v_ = 0.0f; // shared with the audio interrupt
Oscillator osc;
Envelope env;
LowPassGate gate;

/** Apply the starting parameters. Call once, before
 *  AudioEngine::begin(). */
inline void setup() {
  pitchRange.setOutput(110.0f, 880.0f);
  pitchRange.setExponential(true);
  button.begin();
  pinMode(PC13, OUTPUT);
  osc.setWaveform(Waveform::SAW);
  osc.setAmplitude(0.5f);
  env.setAttack(0.01f);
  env.setRelease(0.8f);
  gate.setControl(0.0f);
}

/**
 * Read knobs and switches, drive LEDs. Call from loop(), often;
 * never from the audio interrupt (analogRead() is too slow).
 */
inline void control() {
  pitch.update();
  pitch_v_ = pitch.read();
  button.update();
  button_v_ = button.isHeld() ? 1.0f : 0.0f;
  digitalWrite(PC13, light_v_ > 0.5f ? LOW : HIGH);
}

/**
 * Run every module for one sample, in signal order.
 * @param left   Left output
 * @param right  Right output
 */
inline void process(float &left, float &right) {
  // Control rate: update modulated setters once every 32 samples.
  const bool ctl_ = ++ctl_count_ >= 32;
  if (ctl_)
    ctl_count_ = 0;
  auto pitchRange_v_ = pitchRange.process(pitch_v_);
  light_v_ = button_v_;
  if (ctl_)
    osc.setFrequency(0.0f + 1.0f * pitchRange_v_);
  auto osc_v_ = osc.process();
  env.gate((button_v_) > 0.5f);
  auto env_v_ = env.process();
  if (ctl_)
    gate.setControl(0.0f + 1.0f * env_v_);
  auto gate_v_ = gate.process(osc_v_);
  left = gate_v_;
  right = gate_v_;
}

} // namespace patch
